var n=`1345-sopa-de-mani`;var t=`world-1345`;var a=`BO`;var o=`south-america`;var s=4;var r=65;var m={en:`Sopa de Maní`,ua:`Арахісовий суп`};var g={en:`Sopa de Maní is a dish from Bolivia featuring peanut, yellow onion, garlic, carrot. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Арахісовий суп, страва кухні країни Болівія з такими основними складниками: арахіс, жовта цибуля, часник, морква. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var l=[{en:`Toast these ingredients over medium heat for about 9 minutes, turning frequently to prevent scorching.`,ua:`Підсмажуйте зазначені складники на середньому вогні приблизно 9 хвилин, часто перевертаючи, щоб не підгоріли.`,t:[`dry-toasting`],m:9,i:[[`peanut`,210,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`yellow-onion`,175,`g`],[`garlic`,5,`clove`],[`carrot`,210,`g`],[`canola-oil`,35,`ml`]]},{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 35 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 35 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:35,i:[[`beef-stock`,1200,`ml`],[`potato`,360,`g`],[`ground-cumin`,5,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:8,i:[[`whole-cow-milk`,180,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`parsley`,25,`g`]]}];var u={slug:n,id:t,country:`BO`,region:o,servings:4,minutes:65,title:m,text:g,steps:l};export{a as country,u as default,t as id,r as minutes,o as region,s as servings,n as slug,l as steps,g as text,m as title};